333		if w2, a, err := s.ApplyWaiver("s1", "r1", "w1", "证明材料"); err != nil ||
334			a != ActionExisted || w2.Status != WaiverRevoked {
335			t.Fatalf("重试已撤销申请不应使其生效，得到 %+v action=%v err=%v", w2, a, err)
336		}
337	
338		// 有通过记录的要求：撤销免修后继续满足。
339		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
340		if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
341			t.Fatal(err)
342		}
343		rep = s.CheckStudent("s1")
344		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
345			t.Fatalf("撤销免修但有通过记录时应继续满足，得到学分=%d 未满足=%v",
346				rep.TotalCredits, rep.Unmet)
347		}
348		if rep.Requirements[0].Source != "enrollment" ||
349			rep.Requirements[0].PassedEnrollmentID != "e1" {
350			t.Fatal("撤销免修后应改以通过修读说明来源")
351		}
352	
353		// 已拒绝的申请不能撤销。
354		if _, _, err := s.ApplyWaiver("s1", "r1", "wbad", ""); err != nil {
355			t.Fatal(err)
356		}
357		if _, _, err := s.RevokeWaiver("s1", "wbad", ""); err == nil {
358			t.Fatal("撤销已拒绝的申请应报错")
359		}
360	}
361	
362	func TestWaiverAndPassCountOnceWithWaiverSource(t *testing.T) {
363		s := NewStore()
364		mustStudent(t, s, "s1")
365		mustCourse(t, s, "c1", "数学", 4)
366		mustReq(t, s, "s1", "r1", "c1")
367		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
368		if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
369			t.Fatal(err)
370		}
371		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "免修依据"); err != nil {
372			t.Fatal(err)
373		}
374	
375		rep := s.CheckStudent("s1")
376		if rep.TotalCredits != 4 {
377			t.Fatalf("通过与有效免修并存只应计一次学分，得到 %d", rep.TotalCredits)
378		}
379		st := rep.Requirements[0]
380		if st.Source != "waiver" || st.WaiverID != "w1" {
381			t.Fatalf("有有效免修时应以免修说明当前来源，得到 %+v", st)
382		}
383		if len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "e1" {
384			t.Fatalf("修读历史应同时保留，得到 %v", st.PassedEnrollmentIDs)
385		}
386	}
387	
388	func TestCheckUnknownStudentAndReport(t *testing.T) {
389		s := NewStore()
390		rep := s.CheckStudent("nobody")
391		if rep.Found {
392			t.Fatal("没有记录的学生应返回不存在结果")
393		}
394	
395		mustStudent(t, s, "s1")
396		mustCourse(t, s, "c1", "数学", 4)
397		mustCourse(t, s, "c2", "物理", 3)
398		mustReq(t, s, "s1", "r1", "c1")
399		mustReq(t, s, "s1", "r2", "c2")
400		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
401		if _, _, err := s.SubmitResult("s1", "e1", Failed); err != nil {
402			t.Fatal(err)
403		}
404		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "竞赛获奖"); err != nil {
405			t.Fatal(err)
406		}
407	
408		rep = s.CheckStudent("s1")
409		if rep.TotalCredits != 3 {
410			t.Fatalf("未通过不计学分、免修计学分，总学分应为 3，得到 %d", rep.TotalCredits)
411		}
412		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
413			t.Fatalf("未满足要求应为 [r1]，得到 %v", rep.Unmet)
414		}
415		if len(rep.Requirements) != 2 {
416			t.Fatalf("应列出全部 2 项要求，得到 %d", len(rep.Requirements))
417		}
418		if rep.Requirements[0].Satisfied {
419			t.Fatalf("r1 只有未通过，应未满足，得到 %+v", rep.Requirements[0])
420		}
421		if !rep.Requirements[1].Satisfied || rep.Requirements[1].Source != "waiver" ||
422			rep.Requirements[1].WaiverID != "w1" {
423			t.Fatalf("r2 应由有效免修满足，得到 %+v", rep.Requirements[1])
